package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)

	ans := 0
	met := false

	for scanner.Scan() {
		input := scanner.Text()
		temp := strings.Count(input, "B")

		if input == "BBBBBBBB" {
			ans++
		} else if !met {
			if temp != 0 {
				ans += temp
			}
			met = true
		}
	}

	fmt.Println(ans)
}
